package kr.geumyi.velocitybridge;

import java.io.DataInput;
import java.io.DataOutput;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Deliberately INERT status-only byte-frame adapter for offline and disposable
 * CI. The class does not open a pipe, register a Velocity event, inspect a
 * player list, persist a key, or call ANY lifecycle API.
 *
 * The decoder accepts a canonical, ASCII-only Go Challenge JSON schema in
 * exactly the order generated by velocitybridge.MarshalChallengeFrame.
 * Unsupported JSON (including duplicate fields, escaped strings, different
 * field orders, trailing data or additional fields) fails closed rather than
 * relying on an unsafe regex-based general-purpose JSON parser.
 *
 * This restricted wire profile is NOT a general JSON parser. If the Go schema
 * changes, CI MUST fail until both sides explicitly revise this contract.
 */
public final class StatusOnlyWire {
    private static final int MAX_FRAME = 2048;
    private static final int MAX_CHALLENGE_SECONDS = 20;
    private static final Pattern CHALLENGE = Pattern.compile(
        "\\A\\{\"target\":\"(wild|playground|other)\",\"operation\":\"status\","
        + "\"generation\":\"([A-Za-z0-9_.:-]{8,128})\","
        + "\"nonce\":\"([A-Za-z0-9_-]{32,64})\","
        + "\"issued_unix\":([1-9][0-9]{0,12}),"
        + "\"expires_unix\":([1-9][0-9]{0,12})\\}\\z"
    );

    private StatusOnlyWire() { }

    public record Challenge(
        String target, String generation, String nonce,
        long issuedUnix, long expiresUnix
    ) { }

    /**
     * Strict parser for a bounded frame body, not for arbitrary JSON.
     * Validates current freshness independently of the GSC challenge ledger.
     */
    public static Challenge parseChallenge(byte[] body, Instant now) throws IOException {
        if (body == null || now == null || body.length <= 0
                || body.length > MAX_FRAME) {
            throw new IOException("missing or oversized status challenge");
        }
        for (byte b : body) {
            if (b < 0x20 || b > 0x7e) {
                throw new IOException("challenge not canonical printable ASCII");
            }
        }
        String literal = new String(body, StandardCharsets.US_ASCII);
        Matcher matcher = CHALLENGE.matcher(literal);
        if (!matcher.matches()) {
            throw new IOException("unknown or ambiguous status challenge fields");
        }
        long issued;
        long expires;
        try {
            issued = Long.parseLong(matcher.group(4));
            expires = Long.parseLong(matcher.group(5));
        } catch (NumberFormatException e) {
            throw new IOException("status challenge timestamp out of bounds", e);
        }
        long nowUnix = now.getEpochSecond();
        if (issued <= 0 || expires <= issued
                || expires - issued > MAX_CHALLENGE_SECONDS
                || issued > nowUnix + 5 || issued < nowUnix - 30
                || expires <= nowUnix) {
            throw new IOException("expired or future status challenge");
        }
        return new Challenge(
            matcher.group(1), matcher.group(2), matcher.group(3),
            issued, expires);
    }

    /**
     * Never infer a trusted caller from HMAC alone: OS pipe peer identity,
     * executable attestation and key custody are separate prerequisites.
     * This can be called ONLY by a test-owned stream or, in the future,
     * after a reviewed authenticated OS-pipe adapter is established.
     */
    public static void respond(
        DataInput input, DataOutput output, byte[] key,
        String expectedTarget, String expectedGeneration, Instant now
    ) throws IOException {
        if (input == null || output == null || key == null
                || key.length < 32 || now == null
                || !BridgeEnvelope.isTarget(expectedTarget)
                || expectedGeneration == null
                || !expectedGeneration.matches("[A-Za-z0-9_.:-]{8,128}")) {
            throw new IOException("missing offline status-only credentials/scope");
        }
        int size = input.readInt();
        if (size <= 0 || size > MAX_FRAME) {
            throw new IOException("status frame exceeds 2048 bytes");
        }
        byte[] body = new byte[size];
        input.readFully(body);
        Challenge parsed = parseChallenge(body, now);
        if (!expectedTarget.equals(parsed.target())
                || !expectedGeneration.equals(parsed.generation())) {
            throw new IOException("wrong target or JVM generation");
        }
        BridgeEnvelope.Message message = BridgeEnvelope.signIssuedStatusChallenge(
            key, parsed.target(), parsed.generation(), parsed.nonce(),
            parsed.issuedUnix(), parsed.expiresUnix());
        String response = "{\"version\":1,\"target\":\"" + message.target()
            + "\",\"operation\":\"status\",\"generation\":\"" + message.generation()
            + "\",\"nonce\":\"" + message.nonce()
            + "\",\"issued_unix\":" + message.issuedUnix()
            + ",\"expires_unix\":" + message.expiresUnix()
            + ",\"mac\":\"" + message.mac() + "\"}";
        byte[] wire = response.getBytes(StandardCharsets.US_ASCII);
        if (wire.length <= 0 || wire.length > MAX_FRAME) {
            throw new IOException("signed status response size invalid");
        }
        output.writeInt(wire.length);
        output.write(wire);
    }
}
